using System;using System.IO;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows.Forms;
public static class UpdaterMain {
 public static void Apply(string source,string target,string backup){source=Path.GetFullPath(source);target=Path.GetFullPath(target);backup=Path.GetFullPath(backup);if(!Directory.Exists(source)||!File.Exists(Path.Combine(source,"YuriMusic-YouTube.exe")))throw new IOException("Pacote incompleto.");var changed=new List<string>();var created=new HashSet<string>();try{foreach(string file in Directory.GetFiles(source,"*",SearchOption.AllDirectories)){string rel=file.Substring(source.Length).TrimStart(Path.DirectorySeparatorChar);string dst=Path.Combine(target,rel);if(File.Exists(dst)){string old=Path.Combine(backup,rel);Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(dst,old,true);}else created.Add(rel);changed.Add(rel);Directory.CreateDirectory(Path.GetDirectoryName(dst));File.Copy(file,dst,true);}}catch{for(int i=changed.Count-1;i>=0;i--){string rel=changed[i],dst=Path.Combine(target,rel);if(created.Contains(rel)){if(File.Exists(dst))File.Delete(dst);}else{string old=Path.Combine(backup,rel);if(File.Exists(old))File.Copy(old,dst,true);}}throw;}}
 [STAThread]public static void Main(string[] args){if(args.Length!=4||args[0]!="--apply")return;string stage=Path.GetFullPath(args[1]),target=Path.GetFullPath(args[2]);try{int pid=int.Parse(args[3]);try{using(var parent=Process.GetProcessById(pid)){if(!parent.WaitForExit(45000))throw new IOException("Feche o Yuri Music e tente atualizar novamente.");}}catch(ArgumentException){}Thread.Sleep(700);string source=Path.Combine(stage,"payload");Apply(source,target,Path.Combine(stage,"backup"));File.WriteAllText(Path.Combine(stage,"result.txt"),"ok");Process.Start(new ProcessStartInfo(Path.Combine(target,"YuriMusic-YouTube.exe")){UseShellExecute=true,WorkingDirectory=target});}catch(Exception error){try{File.WriteAllText(Path.Combine(stage,"result.txt"),error.ToString());}catch{}MessageBox.Show("Não foi possível concluir a atualização. Os arquivos anteriores foram restaurados quando necessário.\n"+error.Message,"Yuri Music");}}
}
